import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Settings","description":"Configure GateKeeper from the admin UI - no restart required.","frontmatter":{"title":"Settings","description":"Configure GateKeeper from the admin UI - no restart required."},"headers":[],"relativePath":"admin/settings.md","filePath":"admin/settings.md"}'),s={name:"admin/settings.md"};function i(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<p>The settings page at <code>/admin/settings</code> lets you configure GateKeeper while it is running. All changes apply immediately with no restart.</p><h2 id="access-control" tabindex="-1">Access control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access control&quot;">​</a></h2><h3 id="allowed-email-domains" tabindex="-1">Allowed email domains <a class="header-anchor" href="#allowed-email-domains" aria-label="Permalink to &quot;Allowed email domains&quot;">​</a></h3><p>A comma-separated list of email domains permitted to log in or be created.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com, contractor.org</span></span></code></pre></div><p>Leave blank to allow any email address. When a domain list is set, attempts from other domains fail with an &quot;invalid credentials&quot; error (indistinguishable from a wrong password, to avoid revealing whether an account exists).</p><h3 id="session-timeout" tabindex="-1">Session timeout <a class="header-anchor" href="#session-timeout" aria-label="Permalink to &quot;Session timeout&quot;">​</a></h3><p>How many hours a session stays alive after the last authenticated request. Resets on every request, so active users are never logged out. Default is 8 hours, maximum is 720 (30 days).</p><h2 id="smtp" tabindex="-1">SMTP <a class="header-anchor" href="#smtp" aria-label="Permalink to &quot;SMTP&quot;">​</a></h2><p>GateKeeper sends email for two purposes: one-time login codes and password reset links. Without working SMTP, users cannot complete email OTP login or recover their passwords.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Host</td><td>SMTP server hostname, e.g. <code>smtp.fastmail.com</code></td></tr><tr><td>Port</td><td><code>587</code> for STARTTLS, <code>465</code> for TLS, <code>25</code> for plain</td></tr><tr><td>Username</td><td>SMTP authentication username</td></tr><tr><td>Password</td><td>Leave blank to keep the current value</td></tr><tr><td>From address</td><td>The &quot;from&quot; field on all outgoing emails</td></tr><tr><td>TLS mode</td><td><code>STARTTLS</code> (port 587), <code>TLS</code> (port 465), or <code>None</code></td></tr></tbody></table><p>Click <strong>Send test</strong> to verify your SMTP config sends a message to the From address.</p><h2 id="oidc-provider" tabindex="-1">OIDC provider <a class="header-anchor" href="#oidc-provider" aria-label="Permalink to &quot;OIDC provider&quot;">​</a></h2><p>Read-only information about GateKeeper&#39;s OIDC configuration:</p><ul><li><strong>Issuer</strong> - the base URL, used as the OIDC issuer identifier</li><li><strong>Discovery</strong> - <code>/.well-known/openid-configuration</code></li><li><strong>Signing</strong> - RS256, keys rotate every 30 days automatically</li></ul><h2 id="forwardauth-snippet" tabindex="-1">ForwardAuth snippet <a class="header-anchor" href="#forwardauth-snippet" aria-label="Permalink to &quot;ForwardAuth snippet&quot;">​</a></h2><p>A ready-to-paste config snippet for protecting apps via ForwardAuth. See the <a href="/integrations/traefik-forwardauth.html">Traefik ForwardAuth integration</a> for the full setup guide.</p><h2 id="unsaved-changes" tabindex="-1">Unsaved changes <a class="header-anchor" href="#unsaved-changes" aria-label="Permalink to &quot;Unsaved changes&quot;">​</a></h2><p>When you edit any field, a sticky save bar appears at the bottom of the page. Click <strong>Save changes</strong> to apply, or <strong>Discard</strong> to revert all edits. Changes are not applied until you save.</p><h2 id="env-var-fallbacks" tabindex="-1">Env var fallbacks <a class="header-anchor" href="#env-var-fallbacks" aria-label="Permalink to &quot;Env var fallbacks&quot;">​</a></h2><p>All settings on this page can be pre-seeded via environment variables (see <a href="/getting-started/configuration.html">Configuration</a>). The UI value always takes precedence over an env var. If no UI value has been saved, the env var value is shown as the default.</p>',21)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
